from PyQt5 import QtWidgets, uic

def verif(x):
    if len(x) == 4 and x.isnumeric():
        return True
    else:
        return False
    
def tri(ch):
    if verif(ch):
        i = 0
        x = ch
        y = ch
        while i < len(x) -1 :
            for j in range( len(x)-1 ) :
                if x[j] < x[j+1] :
                    x = x[:j] + x[j+1] + x[j] + x[j+2:]
            for j in range( len(y)-1 ) :
                if y[j] > y[j+1] :
                    y = y[:j] + y[j+1] + y[j] + y[j+2:]
            i += 1
        while(y[0]=="0"):
            y = y[1:]
        p.t2.setText(x)
        p.t3.setText(y)
    else :
        p.t2.setText("INPUT ERROR")
        p.t3.setText("INPUT ERROR")
def effacer():
    p.t1.setText("")
    p.t2.setText("")
    p.t3.setText("")
    p.t1.setFocus()        
    
app = QtWidgets.QApplication([])
p = uic.loadUi("trier_les_caracteres_dune_chaine.ui")
p.show()
p.pb1.clicked.connect(lambda:tri(p.t1.text()))
p.pb2.clicked.connect(effacer)
app.exec_()

